import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface LeavePeriod {
  id: string;
  validFrom: string;
  /** Empty while the period is open. */
  validUntil?: string;
}

export interface ReturnNotice {
  id: string;
  reportedAt: string;
}

export interface LeaveResponse {
  leavePeriods: LeavePeriod[];
  /** Return notices already reported for the claim. */
  returnNotices?: ReturnNotice[];
}

@Injectable({ providedIn: 'root' })
export class LeaveApiService {
  private readonly http = inject(HttpClient);

  getLeave(claimNumber: string): Promise<LeaveResponse> {
    return firstValueFrom(this.http.get<LeaveResponse>(`/api/claims/${encodeURIComponent(claimNumber)}/leave`));
  }
}

