import { Component, ElementRef, inject } from '@angular/core';
import { Router } from '@angular/router';

import { AnalyticsService } from '../../shared/analytics/analytics.service';
import { LeaveApiService } from '../api/leave-api.service';
import { LeaveModalService } from '../leave/services/leave-modal.service';
import { ClaimStore } from '../claim.store';

@Component({
  selector: 'app-claim-detail',
  templateUrl: './claim-detail.component.html',
})
export class ClaimDetailComponent {
  private readonly analytics = inject(AnalyticsService);
  private readonly leaveApi = inject(LeaveApiService);
  private readonly leaveModal = inject(LeaveModalService);
  private readonly router = inject(Router);
  private readonly elementRef = inject(ElementRef);
  private readonly claim = inject(ClaimStore).claim;

  protected async onReportReturnClick($event: MouseEvent): Promise<void> {
    $event.preventDefault();
    this.analytics.sendCtaClick('Report full return to work', 'link');
    const claimNumber = this.claim().claimNumber ?? '';
    const { leavePeriods, returnNotices } =
      await this.leaveApi.getLeave(claimNumber);
    if (returnNotices?.length) {
      this.leaveModal
        .openExistingReturnNotice(this.elementRef, claimNumber, returnNotices[0].id)
        .subscribe(() => void this.router.navigate(['return-notice', 'new', claimNumber]));
      return;
    }
    if (leavePeriods.length === 0) {
      this.leaveModal
        .openNoLeavePeriod(this.elementRef)
        .subscribe(() => this.openLeavePeriodForm());
      return;
    }
    const open = leavePeriods.filter((p) => !p.validUntil);
    if (open.length) {
      this.leaveModal
        .openEndDate(this.elementRef, claimNumber, open[0].id)
        .subscribe(() => void this.router.navigate(['return-notice', 'new', claimNumber]));
      return;
    }
    void this.router.navigate(['return-notice', 'new', claimNumber]);
  }

  private openLeavePeriodForm(): void {
    void this.router.navigate(['leave-period', 'new', this.claim().claimNumber]);
  }
}
